<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Boleto confirmado · NavegaYA</title>@vite(['resources/css/app.css','resources/js/app.js'])<style>body{margin:0;background:#f4f7f6;color:#173b33}.wrap{max-width:900px;margin:24px auto;padding:0 20px}.ticket{margin-top:15px;padding:24px;border:1px solid #dce8e3;border-radius:18px;background:#fff}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.grid span{display:block;color:#6b8179;font-size:11px}.qr{display:flex;gap:20px;align-items:center;margin-top:18px}.qr img{width:145px}.button{display:inline-block;margin-top:15px;padding:11px 15px;border-radius:10px;background:#f2b624;color:#173b33;font-weight:850;text-decoration:none}</style></head><body><x-public-nav current="travels" /><main class="wrap"><h1>Boletos confirmados</h1>@foreach($reservation->seats as $seat)@php($isAir=$reservation->isAir()) @php($trip=$isAir?$reservation->airDeparture:$reservation->departure) @php($route=$isAir?$trip->airRoute:$trip->transportRoute)<article class="ticket"><small>{{$isAir?'✈ VIAJE AÉREO':'⛴ VIAJE FLUVIAL'}}</small><h2>{{$seat->passenger_name}}</h2><div class="grid"><div><span>Ruta</span><strong>{{$isAir?$route->origin_city:$route->originPort->city}} → {{$isAir?$route->destination_city:$route->destinationPort->city}}</strong></div><div><span>Salida</span><strong>{{$trip->departure_at->format('d/m/Y · H:i')}}</strong></div><div><span>Asiento</span><strong>{{$isAir?$seat->aircraftSeat->code:$seat->seat->code}}</strong></div></div><div class="qr"><img src="{{route('tickets.qr',$seat->ticket->code)}}"><div><strong>QR y código seguro de abordaje</strong><br>Reserva {{$reservation->code}}<br>Boleto {{$seat->ticket->code}}<br><a class="button" href="{{route('tickets.pdf',$seat->ticket->code)}}">Descargar PDF</a></div></div></article>@endforeach</main><x-public-footer /></body></html>
